import{_ as e}from"./chunks/en_editace_domeny.DnmVV4IM.js";import{_ as o,o as i,c as a,aa as n}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/media/cs/diary/expired_trial_period.png",w=JSON.parse('{"title":"Switching to Paid Mode","description":"","frontmatter":{"title":"Switching to Paid Mode","wiki":"en:firstofall:payment"},"headers":[],"relativePath":"en/firstofall/payment.md","filePath":"en/firstofall/payment.md","lastUpdated":1794388980000}'),s={name:"en/firstofall/payment.md"};function d(l,t,c,p,u,h){return i(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="switching-to-paid-mode" tabindex="-1">Switching to Paid Mode <a class="header-anchor" href="#switching-to-paid-mode" aria-label="Permalink to &quot;Switching to Paid Mode&quot;">​</a></h1><p>Your monthly trial period begins when you create your account. During this period, you can use the full range of <strong>Buildary</strong> functionality. At the end of this one-month trial period, the application will ask whether you want to switch to paid mode.</p><figure class="shot" style="--w:400px;"><img src="'+r+'" alt="Paid Mode Option" width="400" loading="lazy"></figure><p>If you <strong>do not want to continue in paid mode</strong>, you do not need to do anything. Your use of <strong>Buildary</strong> will simply be limited to projects you have been invited to and that are therefore paid for by someone else. This does not mean that you can no longer work in <strong>Buildary</strong>, but you will not be able to work on your own projects. You can still change your decision later (within 3 months) and switch your domain to paid mode.</p><figure class="shot" style="--w:600px;"><img src="'+e+'" alt="Switching to Paid Mode" width="900" loading="lazy"></figure><p>If you <strong>want to switch to paid mode</strong>, go to <strong>Domain Settings</strong>, enter your billing details, and click <strong>Switch to Paid Mode</strong>. Please note that you must <strong>Save</strong> the page using the button in the bottom-right corner. Billing takes place once every 3 months in arrears, always for a specific project, at a rate based on the number of users on the project. See <a href="http://www.buildary.online/cs/cena-cz" target="_blank" rel="noreferrer">http://www.buildary.online/cs/cena-cz</a> or <a href="http://www.buildary.online/sk/cena" target="_blank" rel="noreferrer">http://www.buildary.online/sk/cena</a></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>In addition to the standard mode described above, individual terms and conditions can be agreed upon. We will switch domains with an individual contract to individual mode. If you are interested in individual terms and conditions, contact us at <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</p></div>',7)])])}const f=o(s,[["render",d]]);export{w as __pageData,f as default};
